43	// Default traits struct defining the internal variable types for the cholesky function
44	template <bool LowerTriangularL, int RowsColsA, typename InputType, typename OutputType>
45	struct choleskyTraits {
46	    typedef InputType PROD_T;
47	    typedef InputType ACCUM_T;
48	    typedef InputType ADD_T;
49	    typedef InputType DIAG_T;
50	    typedef InputType RECIP_DIAG_T;
51	    typedef InputType OFF_DIAG_T;
52	    typedef OutputType L_OUTPUT_T;
53	    static const int ARCH =
54	        1; // Select implementation: 0=Basic, 1=Lower latency architecture, 2=Further improved latency architecture
55	    static const int INNER_II = 1; // Specify the pipelining target for the inner loop
56	    static const int UNROLL_FACTOR =
57	        1; // Specify the inner loop unrolling factor for the choleskyAlt2 architecture(2) to increase throughput
58	    static const int UNROLL_DIM = (LowerTriangularL == true ? 1 : 2); // Dimension to unroll matrix
59	    static const int ARCH2_ZERO_LOOP =
60	        true; // Additional implementation "switch" for the choleskyAlt2 architecture (2).
61	};
