98	template <bool LowerTriangularL,
99	          int RowsColsA,
100	          int W1,
101	          int I1,
102	          ap_q_mode Q1,
103	          ap_o_mode O1,
104	          int N1,
105	          int W2,
106	          int I2,
107	          ap_q_mode Q2,
108	          ap_o_mode O2,
109	          int N2>
110	struct choleskyTraits<LowerTriangularL, RowsColsA, ap_fixed<W1, I1, Q1, O1, N1>, ap_fixed<W2, I2, Q2, O2, N2> > {
111	    typedef ap_fixed<W1 + W1, I1 + I1, AP_RND_CONV, AP_SAT, 0> PROD_T;
112	    typedef ap_fixed<(W1 + W1) + BitWidth<RowsColsA>::Value,
113	                     (I1 + I1) + BitWidth<RowsColsA>::Value,
114	                     AP_RND_CONV,
115	                     AP_SAT,
116	                     0>
117	        ACCUM_T;
118	    typedef ap_fixed<W1 + 1, I1 + 1, AP_RND_CONV, AP_SAT, 0> ADD_T;
119	    typedef ap_fixed<(W1 + 1) * 2, I1 + 1, AP_RND_CONV, AP_SAT, 0> DIAG_T;     // Takes result of sqrt
120	    typedef ap_fixed<(W1 + 1) * 2, I1 + 1, AP_RND_CONV, AP_SAT, 0> OFF_DIAG_T; // Takes result of /
121	    typedef ap_fixed<2 + (W2 - I2) + W2, 2 + (W2 - I2), AP_RND_CONV, AP_SAT, 0> RECIP_DIAG_T;
122	    typedef ap_fixed<W2, I2, AP_RND_CONV, AP_SAT, 0>
123	        L_OUTPUT_T; // Takes new L value.  Same as L output but saturation set
124	    static const int ARCH = 1;
125	    static const int INNER_II = 1;
126	    static const int UNROLL_FACTOR = 1;
127	    static const int UNROLL_DIM = (LowerTriangularL == true ? 1 : 2);
128	    static const int ARCH2_ZERO_LOOP = true;
129	};
