205	// ===================================================================================================================
206	// Helper functions
207	
208	// Square root
209	// o Overloaded versions of the sqrt function
210	// o The square root of a complex number is expensive.  However, the diagonal values of a Cholesky decomposition are
211	// always
212	//   real so we don't need a full complex square root.
213	template <typename T_IN, typename T_OUT>
214	int cholesky_sqrt_op(T_IN a, T_OUT& b) {
215	Function_cholesky_sqrt_op_real:;
216	    const T_IN ZERO = 0;
217	    if (a < ZERO) {
218	        b = ZERO;
219	        return (1);
220	    }
221	    b = x_sqrt(a);
222	    return (0);
223	}
224	template <typename T_IN, typename T_OUT>
225	int cholesky_sqrt_op(hls::x_complex<T_IN> din, hls::x_complex<T_OUT>& dout) {
226	Function_cholesky_sqrt_op_complex:;
227	    const T_IN ZERO = 0;
228	    T_IN a = din.real();
229	    dout.imag(ZERO);
230	
231	    if (a < ZERO) {
232	        dout.real(ZERO);
233	        return (1);
234	    }
235	
236	    dout.real(x_sqrt(a));
237	    return (0);
238	}
239	template <typename T_IN, typename T_OUT>
240	int cholesky_sqrt_op(std::complex<T_IN> din, std::complex<T_OUT>& dout) {
241	Function_cholesky_sqrt_op_complex:;
242	    const T_IN ZERO = 0;
243	    T_IN a = din.real();
244	    dout.imag(ZERO);
245	
246	    if (a < ZERO) {
247	        dout.real(ZERO);
248	        return (1);
249	    }
250	
251	    dout.real(x_sqrt(a));
252	    return (0);
253	}
254	
255	// Reciprocal square root.
256	template <typename InputType, typename OutputType>
257	void cholesky_rsqrt(InputType x, OutputType& res) {
258	Function_cholesky_rsqrt_default:;
259	    res = x_rsqrt(x);
260	}
261	template <int W1, int I1, ap_q_mode Q1, ap_o_mode O1, int N1, int W2, int I2, ap_q_mode Q2, ap_o_mode O2, int N2>
262	void cholesky_rsqrt(ap_fixed<W1, I1, Q1, O1, N1> x, ap_fixed<W2, I2, Q2, O2, N2>& res) {
263	Function_cholesky_rsqrt_fixed:;
264	    ap_fixed<W2, I2, Q2, O2, N2> one = 1;
265	    ap_fixed<W1, I1, Q1, O1, N1> sqrt_res;
266	    ap_fixed<W2, I2, Q2, O2, N2> sqrt_res_cast;
267	    sqrt_res = x_sqrt(x);
268	    sqrt_res_cast = sqrt_res;
269	    res = one / sqrt_res_cast;
270	}
