272	// Local multiplier to handle a complex case currently not supported by the hls::x_complex class
273	// - Complex multiplied by a real of a different type
274	// - Required for complex fixed point implementations
275	template <typename AType, typename BType, typename CType>
276	void cholesky_prod_sum_mult(AType A, BType B, CType& C) {
277	Function_cholesky_prod_sum_mult_real:;
278	    C = A * B;
279	}
280	template <typename AType, typename BType, typename CType>
281	void cholesky_prod_sum_mult(hls::x_complex<AType> A, BType B, hls::x_complex<CType>& C) {
282	Function_cholesky_prod_sum_mult_complex:;
283	    C.real(A.real() * B);
284	    C.imag(A.imag() * B);
285	}
286	template <typename AType, typename BType, typename CType>
287	void cholesky_prod_sum_mult(std::complex<AType> A, BType B, std::complex<CType>& C) {
288	Function_cholesky_prod_sum_mult_complex:;
289	    C.real(A.real() * B);
290	    C.imag(A.imag() * B);
291	}
