293	// ===================================================================================================================
294	// choleskyBasic
295	template <bool LowerTriangularL, int RowsColsA, typename CholeskyTraits, class InputType, class OutputType>
296	int choleskyBasic(const InputType A[RowsColsA][RowsColsA], OutputType L[RowsColsA][RowsColsA]) {
297	    int return_code = 0;
298	
299	    // Use the traits struct to specify the correct type for the intermediate variables. This is really only needed for
300	    // fixed point.
301	    typename CholeskyTraits::PROD_T prod;
302	    typename CholeskyTraits::ACCUM_T sum[RowsColsA];
303	    typename CholeskyTraits::ACCUM_T A_cast_to_sum;    // A with the same dimensions as sum.
304	    typename CholeskyTraits::ACCUM_T prod_cast_to_sum; // prod with the same dimensions as sum.
305	
306	    typename CholeskyTraits::ADD_T A_minus_sum;
307	    typename CholeskyTraits::DIAG_T new_L_diag;         // sqrt(A_minus_sum)
308	    typename CholeskyTraits::OFF_DIAG_T new_L_off_diag; // sum/L
309	    typename CholeskyTraits::OFF_DIAG_T L_cast_to_new_L_off_diag;
310	
311	    typename CholeskyTraits::L_OUTPUT_T new_L;
312	    OutputType retrieved_L;
313	    // Internal memory used to aviod read access from function output argument L.
314	    // NOTE: The internal matrix only needs to be triangular but optimization using a 1-D array it will require addition
315	    // logic to generate the indexes. Refer to the choleskyAlt function.
316	    OutputType L_internal[RowsColsA][RowsColsA];
317	
318	col_loop:
319	    for (int j = 0; j < RowsColsA; j++) {
320	        sum[j] = 0;
321	
322	    // Calculate the diagonal value for this column
323	    diag_loop:
324	        for (int k = 0; k < RowsColsA; k++) {
325	            if (k <= (j - 1)) {
326	                if (LowerTriangularL == true) {
327	                    retrieved_L = L_internal[j][k];
328	                } else {
329	                    retrieved_L = L_internal[k][j];
330	                }
331	                sum[j] = hls::x_conj(retrieved_L) * retrieved_L;
332	            }
333	        }
334	        A_cast_to_sum = A[j][j];
335	
336	        A_minus_sum = A_cast_to_sum - sum[j];
337	
338	        if (cholesky_sqrt_op(A_minus_sum, new_L_diag)) {
339	#ifndef __SYNTHESIS__
340	            printf("ERROR: Trying to find the square root of a negative number\n");
341	#endif
342	            return_code = 1;
343	        }
344	
345	        // Round to target format using method specifed by traits defined types.
346	        new_L = new_L_diag;
347	
348	        if (LowerTriangularL == true) {
349	            L_internal[j][j] = new_L;
350	            L[j][j] = new_L;
351	        } else {
352	            L_internal[j][j] = hls::x_conj(new_L);
353	            L[j][j] = hls::x_conj(new_L);
354	        }
355	
356	    // Calculate the off diagonal values for this column
357	    off_diag_loop:
358	        for (int i = 0; i < RowsColsA; i++) {
359	            if (i > j) {
360	                if (LowerTriangularL == true) {
361	                    sum[j] = A[i][j];
362	                } else {
363	                    sum[j] = hls::x_conj(A[j][i]);
364	                }
365	
366	            sum_loop:
367	                for (int k = 0; k < RowsColsA; k++) {
368	#pragma HLS PIPELINE II = CholeskyTraits::INNER_II
369	                    if (k <= (j - 1)) {
370	                        if (LowerTriangularL == true) {
371	                            prod = -L_internal[i][k] * hls::x_conj(L_internal[j][k]);
372	                        } else {
373	                            prod = -hls::x_conj(L_internal[k][i]) * (L_internal[k][j]);
374	                        }
375	
376	                        prod_cast_to_sum = prod;
377	                        sum[j] += prod_cast_to_sum;
378	                    }
379	                }
380	
381	                new_L_off_diag = sum[j];
382	
383	                L_cast_to_new_L_off_diag = L_internal[j][j];
384	
385	                // Diagonal is always real, avoid complex division
386	                new_L_off_diag = new_L_off_diag / hls::x_real(L_cast_to_new_L_off_diag);
387	
388	                // Round to target format using method specifed by traits defined types.
389	                new_L = new_L_off_diag;
390	
391	                if (LowerTriangularL == true) {
392	                    L[i][j] = new_L;
393	                    L_internal[i][j] = new_L;
394	                } else {
395	                    L[j][i] = hls::x_conj(new_L);
396	                    L_internal[j][i] = hls::x_conj(new_L);
397	                }
398	            } else if (i < j) {
399	                if (LowerTriangularL == true) {
400	                    L[i][j] = 0;
401	                } else {
402	                    L[j][i] = 0;
403	                }
404	            }
405	        }
406	    }
407	    return (return_code);
408	}
