410	// ===================================================================================================================
411	// choleskyAlt: Alternative architecture with improved latency at the expense of higher resource
412	template <bool LowerTriangularL, int RowsColsA, typename CholeskyTraits, class InputType, class OutputType>
413	int choleskyAlt(const InputType A[RowsColsA][RowsColsA], OutputType L[RowsColsA][RowsColsA]) {
414	    int return_code = 0;
415	
416	    // Optimize internal memories
417	    // - For complex data types the diagonal will be real only, plus for fixed point it must be stored to a
418	    //   higher precision.
419	    // - Requires additional logic to generate the memory indexes
420	    // - For smaller matrix sizes there maybe be an increase in memory usage
421	    OutputType L_internal[(RowsColsA * RowsColsA - RowsColsA) / 2];
422	    typename CholeskyTraits::RECIP_DIAG_T diag_internal[RowsColsA];
423	
424	    typename CholeskyTraits::ACCUM_T square_sum;
425	    typename CholeskyTraits::ACCUM_T A_cast_to_sum;
426	    typename CholeskyTraits::ADD_T A_minus_sum;
427	    typename CholeskyTraits::DIAG_T A_minus_sum_cast_diag;
428	    typename CholeskyTraits::DIAG_T new_L_diag;
429	    typename CholeskyTraits::RECIP_DIAG_T new_L_diag_recip;
430	    typename CholeskyTraits::PROD_T prod;
431	    typename CholeskyTraits::ACCUM_T prod_cast_to_sum;
432	    typename CholeskyTraits::ACCUM_T product_sum;
433	    typename CholeskyTraits::OFF_DIAG_T prod_cast_to_off_diag;
434	    typename CholeskyTraits::RECIP_DIAG_T L_diag_recip;
435	    typename CholeskyTraits::OFF_DIAG_T new_L_off_diag;
436	    typename CholeskyTraits::L_OUTPUT_T new_L;
437	    typename CholeskyTraits::L_OUTPUT_T new_L_recip;
438	
439	row_loop:
440	    for (int i = 0; i < RowsColsA; i++) {
441	        // Index generation for optimized/packed L_internal memory
442	        int i_sub1 = i - 1;
443	        int i_off = ((i_sub1 * i_sub1 - i_sub1) / 2) + i_sub1;
444	
445	        // Off diagonal calculation
446	        square_sum = 0;
447	    col_loop:
448	        for (int j = 0; j < i; j++) {
449	#pragma HLS loop_tripcount max = 1 + RowsColsA / 2
450	            // Index generation
451	            int j_sub1 = j - 1;
452	            int j_off = ((j_sub1 * j_sub1 - j_sub1) / 2) + j_sub1;
453	            // Prime the off-diagonal sum with target elements A value.
454	            if (LowerTriangularL == true) {
455	                product_sum = A[i][j];
456	            } else {
457	                product_sum = hls::x_conj(A[j][i]);
458	            }
459	        sum_loop:
460	            for (int k = 0; k < j; k++) {
461	#pragma HLS loop_tripcount max = 1 + RowsColsA / 2
462	#pragma HLS PIPELINE II = CholeskyTraits::INNER_II
463	                prod = -L_internal[i_off + k] * hls::x_conj(L_internal[j_off + k]);
464	                prod_cast_to_sum = prod;
465	                product_sum += prod_cast_to_sum;
466	            }
467	            prod_cast_to_off_diag = product_sum;
468	            // Fetch diagonal value
469	            L_diag_recip = diag_internal[j];
470	            // Diagonal is stored in its reciprocal form so only need to multiply the product sum
471	            cholesky_prod_sum_mult(prod_cast_to_off_diag, L_diag_recip, new_L_off_diag);
472	            // Round to target format using method specifed by traits defined types.
473	            new_L = new_L_off_diag;
474	            // Build sum for use in diagonal calculation for this row.
475	            square_sum += hls::x_conj(new_L) * new_L;
476	            // Store result
477	            L_internal[i_off + j] = new_L;
478	            if (LowerTriangularL == true) {
479	                L[i][j] = new_L; // store in lower triangle
480	                L[j][i] = 0;     // Zero upper
481	            } else {
482	                L[j][i] = hls::x_conj(new_L); // store in upper triangle
483	                L[i][j] = 0;                  // Zero lower
484	            }
485	        }
486	
487	        // Diagonal calculation
488	        A_cast_to_sum = A[i][i];
489	        A_minus_sum = A_cast_to_sum - square_sum;
490	        if (cholesky_sqrt_op(A_minus_sum, new_L_diag)) {
491	#ifndef __SYNTHESIS__
492	            printf("ERROR: Trying to find the square root of a negative number\n");
493	#endif
494	            return_code = 1;
495	        }
496	        // Round to target format using method specifed by traits defined types.
497	        new_L = new_L_diag;
498	        // Generate the reciprocal of the diagonal for internal use to aviod the latency of a divide in every
499	        // off-diagonal calculation
500	        A_minus_sum_cast_diag = A_minus_sum;
501	        cholesky_rsqrt(hls::x_real(A_minus_sum_cast_diag), new_L_diag_recip);
502	        // Store diagonal value
503	        diag_internal[i] = new_L_diag_recip;
504	        if (LowerTriangularL == true) {
505	            L[i][i] = new_L;
506	        } else {
507	            L[i][i] = hls::x_conj(new_L);
508	        }
509	    }
510	    return (return_code);
511	}
512	
513	// ===================================================================================================================
514	// choleskyAlt2: Further improved latency architecture requiring higher resource
515	template <bool LowerTriangularL, int RowsColsA, typename CholeskyTraits, class InputType, class OutputType>
516	int choleskyAlt2(const InputType A[RowsColsA][RowsColsA], OutputType L[RowsColsA][RowsColsA]) {
517	    int return_code = 0;
518	
519	    // To avoid array index calculations every iteration this architecture uses a simple 2D array rather than a
520	    // optimized/packed triangular matrix.
521	    OutputType L_internal[RowsColsA][RowsColsA];
522	    OutputType prod_column_top;
523	    typename CholeskyTraits::ACCUM_T square_sum_array[RowsColsA];
524	    typename CholeskyTraits::ACCUM_T A_cast_to_sum;
525	    typename CholeskyTraits::ADD_T A_minus_sum;
526	    typename CholeskyTraits::DIAG_T A_minus_sum_cast_diag;
527	    typename CholeskyTraits::DIAG_T new_L_diag;
528	    typename CholeskyTraits::RECIP_DIAG_T new_L_diag_recip;
529	    typename CholeskyTraits::PROD_T prod;
530	    typename CholeskyTraits::ACCUM_T prod_cast_to_sum;
531	    typename CholeskyTraits::ACCUM_T product_sum;
532	    typename CholeskyTraits::ACCUM_T product_sum_array[RowsColsA];
533	    typename CholeskyTraits::OFF_DIAG_T prod_cast_to_off_diag;
534	    typename CholeskyTraits::OFF_DIAG_T new_L_off_diag;
535	    typename CholeskyTraits::L_OUTPUT_T new_L;
536	
537	#pragma HLS ARRAY_PARTITION variable = A cyclic dim = CholeskyTraits::UNROLL_DIM factor = CholeskyTraits::UNROLL_FACTOR
538	#pragma HLS ARRAY_PARTITION variable = L cyclic dim = CholeskyTraits::UNROLL_DIM factor = CholeskyTraits::UNROLL_FACTOR
539	#pragma HLS ARRAY_PARTITION variable = L_internal cyclic dim = CholeskyTraits::UNROLL_DIM factor = \
540	    CholeskyTraits::UNROLL_FACTOR
541	#pragma HLS ARRAY_PARTITION variable = square_sum_array cyclic dim = 1 factor = CholeskyTraits::UNROLL_FACTOR
542	#pragma HLS ARRAY_PARTITION variable = product_sum_array cyclic dim = 1 factor = CholeskyTraits::UNROLL_FACTOR
543	
544	col_loop:
545	    for (int j = 0; j < RowsColsA; j++) {
546	        // Diagonal calculation
547	        A_cast_to_sum = A[j][j];
548	        if (j == 0) {
549	            A_minus_sum = A_cast_to_sum;
550	        } else {
551	            A_minus_sum = A_cast_to_sum - square_sum_array[j];
552	        }
553	        if (cholesky_sqrt_op(A_minus_sum, new_L_diag)) {
554	#ifndef __SYNTHESIS__
555	            printf("ERROR: Trying to find the square root of a negative number\n");
556	#endif
557	            return_code = 1;
558	        }
559	        // Round to target format using method specifed by traits defined types.
560	        new_L = new_L_diag;
561	        // Generate the reciprocal of the diagonal for internal use to aviod the latency of a divide in every
562	        // off-diagonal calculation
563	        A_minus_sum_cast_diag = A_minus_sum;
564	        cholesky_rsqrt(hls::x_real(A_minus_sum_cast_diag), new_L_diag_recip);
565	        // Store diagonal value
566	        if (LowerTriangularL == true) {
567	            L[j][j] = new_L;
568	        } else {
569	            L[j][j] = hls::x_conj(new_L);
570	        }
571	
572	    sum_loop:
573	        for (int k = 0; k <= j; k++) {
574	// Define average trip count for reporting, loop reduces in length for every iteration of col_loop
575	#pragma HLS loop_tripcount max = 1 + RowsColsA / 2
576	            // Same value used in all calcs
577	            // o Implement -1* here
578	            prod_column_top = -hls::x_conj(L_internal[j][k]);
579	
580	        // NOTE: Using a fixed loop length combined with a "if" to implement reducing loop length
581	        // o Ensures the inner loop can achieve the maximum II (1)
582	        // o May introduce a small overhead resolving the "if" statement but HLS struggled to schedule when the variable
583	        //   loop bound expression was used.
584	        // o Will report inaccurate trip count as it will reduce by one with the col_loop
585	        // o Variable loop bound code: row_loop: for(int i = j+1; i < RowsColsA; i++) {
586	        row_loop:
587	            for (int i = 0; i < RowsColsA; i++) {
588	// IMPORTANT: row_loop must not merge with sum_loop as the merged loop becomes variable length and HLS will struggle
589	// with scheduling
590	#pragma HLS LOOP_FLATTEN off
591	#pragma HLS PIPELINE II = CholeskyTraits::INNER_II
592	#pragma HLS UNROLL FACTOR = CholeskyTraits::UNROLL_FACTOR
593	
594	                if (i > j) {
595	                    prod = L_internal[i][k] * prod_column_top;
596	                    prod_cast_to_sum = prod;
597	
598	                    if (k == 0) {
599	                        // Prime first sum
600	                        if (LowerTriangularL == true) {
601	                            A_cast_to_sum = A[i][j];
602	                        } else {
603	                            A_cast_to_sum = hls::x_conj(A[j][i]);
604	                        }
605	                        product_sum = A_cast_to_sum;
606	                    } else {
607	                        product_sum = product_sum_array[i];
608	                    }
609	
610	                    if (k < j) {
611	                        // Accumulate row sum of columns
612	                        product_sum_array[i] = product_sum + prod_cast_to_sum;
613	                    } else {
614	                        // Final calculation for off diagonal value
615	                        prod_cast_to_off_diag = product_sum;
616	                        // Diagonal is stored in its reciprocal form so only need to multiply the product sum
617	                        cholesky_prod_sum_mult(prod_cast_to_off_diag, new_L_diag_recip, new_L_off_diag);
618	                        // Round to target format using method specifed by traits defined types.
619	                        new_L = new_L_off_diag;
620	                        // Build sum for use in diagonal calculation for this row.
621	                        if (k == 0) {
622	                            square_sum_array[j] = hls::x_conj(new_L) * new_L;
623	                        } else {
624	                            square_sum_array[j] = hls::x_conj(new_L) * new_L;
625	                        }
626	                        // Store result
627	                        L_internal[i][j] = new_L;
628	                        // NOTE: Use the upper/lower triangle zeroing in the subsequent loop so the double memory access
629	                        // does not
630	                        // become a bottleneck
631	                        // o Results in a further increase of DSP resources due to the higher II of this loop.
632	                        // o Retaining the zeroing operation here can give this a loop a max II of 2 and HLS will
633	                        // resource share.
634	                        if (LowerTriangularL == true) {
635	                            L[i][j] = new_L;                                   // Store in lower triangle
636	                            if (!CholeskyTraits::ARCH2_ZERO_LOOP) L[j][i] = 0; // Zero upper
637	                        } else {
638	                            L[j][i] = hls::x_conj(new_L);                      // Store in upper triangle
639	                            if (!CholeskyTraits::ARCH2_ZERO_LOOP) L[i][j] = 0; // Zero lower
640	                        }
641	                    }
642	                }
643	            }
644	        }
645	    }
646	    // Zero upper/lower triangle
647	    // o Use separate loop to ensure main calcuation can achieve an II of 1
648	    // o As noted above this may increase the DSP resources.
649	    // o Required when unrolling the inner loop due to array dimension access
650	    if (CholeskyTraits::ARCH2_ZERO_LOOP) {
651	    zero_rows_loop:
652	        for (int i = 0; i < RowsColsA - 1; i++) {
653	        zero_cols_loop:
654	            for (int j = i + 1; j < RowsColsA; j++) {
655	// Define average trip count for reporting, loop reduces in length for every iteration of zero_rows_loop
656	#pragma HLS loop_tripcount max = 1 + RowsColsA / 2
657	#pragma HLS PIPELINE
658	                if (LowerTriangularL == true) {
659	                    L[i][j] = 0; // Zero upper
660	                } else {
661	                    L[j][i] = 0; // Zero lower
662	                }
663	            }
664	        }
665	    }
666	    return (return_code);
667	}
668	
669	// ===================================================================================================================
670	// choleskyTop: Top level function that selects implementation architecture and internal types based on the
671	// traits class provided via the CholeskyTraits template parameter.
672	// o Call this function directly if you wish to override the default architecture choice or internal types
673	template <bool LowerTriangularL, int RowsColsA, typename CholeskyTraits, class InputType, class OutputType>
674	int choleskyTop(const InputType A[RowsColsA][RowsColsA], OutputType L[RowsColsA][RowsColsA]) {
675	    switch (CholeskyTraits::ARCH) {
676	        case 0:
677	            return choleskyBasic<LowerTriangularL, RowsColsA, CholeskyTraits, InputType, OutputType>(A, L);
678	        case 1:
679	            return choleskyAlt<LowerTriangularL, RowsColsA, CholeskyTraits, InputType, OutputType>(A, L);
680	        case 2:
681	            return choleskyAlt2<LowerTriangularL, RowsColsA, CholeskyTraits, InputType, OutputType>(A, L);
682	        default:
683	            return choleskyBasic<LowerTriangularL, RowsColsA, CholeskyTraits, InputType, OutputType>(A, L);
684	    }
685	}
686	
687	/**
688	* @brief cholesky
689	*
690	* @tparam LowerTriangularL   When false generates the result in the upper triangle
691	* @tparam RowsColsA          Defines the matrix dimensions
692	* @tparam InputType          Input data type
693	* @tparam OutputType         Output data type
694	* @tparam TRAITS             choleskyTraits class
695	*
696	* @param matrixAStrm         Stream of Hermitian/symmetric positive definite input matrix
697	* @param matrixLStrm         Stream of Lower or upper triangular output matrix
698	*
699	* @return                    An integer type. 0=Success. 1=Failure. The function attempted to find the square root of
700	* a negative number i.e. the input matrix A was not Hermitian/symmetric positive definite.
701	*/
702	template <bool LowerTriangularL,
703	          int RowsColsA,
704	          class InputType,
705	          class OutputType,
706	          typename TRAITS = choleskyTraits<LowerTriangularL, RowsColsA, InputType, OutputType> >
707	int cholesky(hls::stream<InputType>& matrixAStrm, hls::stream<OutputType>& matrixLStrm) {
708	    InputType A[RowsColsA][RowsColsA];
709	    OutputType L[RowsColsA][RowsColsA];
710	
711	    for (int r = 0; r < RowsColsA; r++) {
712	#pragma HLS PIPELINE
713	        for (int c = 0; c < RowsColsA; c++) {
714	            matrixAStrm.read(A[r][c]);
715	        }
716	    }
717	
718	    int ret = 0;
719	    ret = choleskyTop<LowerTriangularL, RowsColsA, TRAITS, InputType, OutputType>(A, L);
720	
721	    for (int r = 0; r < RowsColsA; r++) {
722	#pragma HLS PIPELINE
723	        for (int c = 0; c < RowsColsA; c++) {
724	            matrixLStrm.write(L[r][c]);
725	        }
726	    }
727	    return ret;
728	}
729	
730	} // end namespace solver
731	} // end namespace xf
732	#endif
