65	    static const int W =
66	        W1 + (W1 - I1) + (W1 - I1);      // Fractional growth is denominator fraction width + numerator full width
67	    static const int I = I1 + (W1 - I1); // Integer growth is denominator int width + numerator fraction width
68	    typedef ap_fixed<W, I, AP_TRN, AP_WRAP, 0> RECIP_T;
69	    typedef ap_fixed<2 * W, 2 * I, AP_TRN, AP_WRAP, 0> MULT_T;
70	    typedef ap_fixed<(2 * W) + 1, (2 * I) + 1, AP_TRN, AP_WRAP, 0> ADD_T;
71	    typedef ap_fixed<2 * W2, 2 * I2, AP_TRN, AP_WRAP, 0> MULTNEG_T;
