131	// Helper functions
132	
133	// IMPLEMENTATION TIP: Force the reciprocal to be implemented using a single-precision divider with the resource
134	// directive.
135	// This permits sharing of operators with the factorization function preceding the back-substitution
136	template <typename T>
137	void back_substitute_recip(T x, T& one_over_x) {
138	    // #pragma HLS BIND_OP variable=one_over_x  op=fdiv impl=fabric
139	    const T ONE = 1.0;
140	    one_over_x = ONE / x;
141	}
142	
143	// All diagonal elements of the factorization (Cholesky or QR) should be real.
144	// We can therefore use a real-valued divider (or reciprocal operator) to compute the diagonal inverse values.
145	//
146	// IMPLEMENTATION TIP: Force the reciprocal to be implemented using a single-precision divider with the resource
147	// directive.
148	// This permits sharing of operators with the factorization function preceding the back-substitution.
149	template <typename T>
150	void back_substitute_recip(hls::x_complex<T> x, hls::x_complex<T>& one_over_x) {
151	    // #pragma HLS BIND_OP variable=recip  op=fdiv impl=fabric
152	    T recip; // intermediate variable to allow directive to be applied
153	    const hls::x_complex<T> ONE = 1.0;
154	    recip = ONE.real() / x.real();
155	    one_over_x.real() = recip;
156	    one_over_x.imag() = 0.0;
157	}
158	
159	template <typename T>
160	void back_substitute_recip(std::complex<T> x, std::complex<T>& one_over_x) {
161	    // #pragma HLS BIND_OP variable=recip  op=fdiv impl=fabric
162	    T recip; // intermediate variable to allow directive to be applied
163	    const std::complex<T> ONE(1.0);
164	    recip = ONE.real() / x.real();
165	    one_over_x.real(recip);
166	    one_over_x.imag(0.0);
167	}
