169	template <int W1, int I1, ap_q_mode Q1, ap_o_mode O1, int N1, int W2, int I2, ap_q_mode Q2, ap_o_mode O2, int N2>
170	void back_substitute_recip(ap_fixed<W1, I1, Q1, O1, N1> x, ap_fixed<W2, I2, Q2, O2, N2>& one_over_x) {
171	    ap_fixed<W2, I2, Q2, O2, N2> ONE = 1; // Size to the output precision
172	    one_over_x = ONE / x;                 // Infers a divider
173	}
174	
175	template <int W1, int I1, ap_q_mode Q1, ap_o_mode O1, int N1, int W2, int I2, ap_q_mode Q2, ap_o_mode O2, int N2>
176	void back_substitute_recip(hls::x_complex<ap_fixed<W1, I1, Q1, O1, N1> > x,
177	                           hls::x_complex<ap_fixed<W2, I2, Q2, O2, N2> >& one_over_x) {
178	    hls::x_complex<ap_fixed<W2, I2, Q2, O2, N2> > ONE; // Size to the output precision
179	    ONE.real() = 1;
180	    ONE.imag() = 0;
181	    one_over_x.real() = ONE.real() / x.real(); // Infers a real-valued divider
182	    one_over_x.imag() = 0;
183	}
