185	template <int W1, int I1, ap_q_mode Q1, ap_o_mode O1, int N1, int W2, int I2, ap_q_mode Q2, ap_o_mode O2, int N2>
186	void back_substitute_recip(std::complex<ap_fixed<W1, I1, Q1, O1, N1> > x,
187	                           std::complex<ap_fixed<W2, I2, Q2, O2, N2> >& one_over_x) {
188	    std::complex<ap_fixed<W2, I2, Q2, O2, N2> > ONE; // Size to the output precision
189	    ONE.real(1);
190	    ONE.imag(0);
191	    one_over_x.real(ONE.real() / x.real()); // Infers a real-valued divider
192	    one_over_x.imag(0);
193	}
