195	// ===================================================================================================================
196	// backSubstituteBasic
197	// o It is assumed that argument B is an internal buffer created in the calling function
198	//   and not an external interface, since the back substitution process reads and writes
199	//   from/to that buffer.
200	template <int RowsColsA, typename BackSubstituteTraits, typename InputType, typename OutputType>
201	void backSubstituteBasic(const InputType A[RowsColsA][RowsColsA],
202	                         OutputType B[RowsColsA][RowsColsA],
203	                         int& is_singular) {
204	    typename BackSubstituteTraits::RECIP_T diag_recip, diag_recip_calc;
205	    OutputType subst_prod_m1;
206	    OutputType subst_prod_m2;
207	    typename BackSubstituteTraits::MULT_T subst_prod;
208	    typename BackSubstituteTraits::ADD_T subst_prod_sum;
209	    typename BackSubstituteTraits::ADD_T subst_sum;
210	    typename BackSubstituteTraits::ADD_T diag_recip_low;
211	    typename BackSubstituteTraits::MULTNEG_T neg_diag_prod;
212	
213	    is_singular = 0;
214	back_substitute_j:
215	    for (int j = 0; j < RowsColsA; j++) {
216	        back_substitute_recip(A[j][j], diag_recip);
217	        B[j][j] = diag_recip;
218	        if (hls::x_real(diag_recip) == 0 && hls::x_imag(diag_recip) == 0) {
219	            is_singular = 1;
220	        }
221	
222	    back_substitute_i:
223	        for (int i = 0; i < RowsColsA; i++) {
224	            if (i >= j) {
225	                if (i == j) {
226	                    continue;
227	                } else {
228	                    B[i][j] = 0; // Sets the lower triangle to zero for the final matrix mult to work
229	                }
230	            } else {
231	                subst_sum = 0; // Equivalent to setting zeros in the upper triangle of the identity matrix we're
232	                               // "inverting against"
233	            back_substitute_k:
234	                for (int k = 0; k < RowsColsA; k++) {
235	#pragma HLS PIPELINE II = BackSubstituteTraits::INNER_II
236	
237	                    if (k >= j) {
238	                        continue;
239	                    } else {
240	                        if (i > k) {
241	                            continue;
242	                        } else {
243	                            subst_prod_m1 = A[k][j]; // For fixed-point, re-size to higher precision of B
244	                            subst_prod_m2 = B[i][k];
245	                            subst_prod = subst_prod_m1 * subst_prod_m2;
246	                            subst_prod_sum = subst_prod; // Resize
247	                            subst_sum += subst_prod_sum;
248	                        }
249	                    }
250	                    diag_recip_low =
251	                        diag_recip; // For fixed-point, reduce precision to match subst_sum for multiplication
252	                    // IMPLEMENTATION TIP: Use last subst_sum value below rather than reading from B to reduce error for
253	                    // fixed-point implementations.
254	                    // Implementing as "neg_diag_prod = -B[i][j] * B[j][j];" for fixed-point increases error by ~10%,
255	                    // but halves
256	                    // the DSP48 usage.
257	                    neg_diag_prod = -subst_sum * diag_recip_low;
258	                    B[i][j] = neg_diag_prod;
259	                } // end i>=j
260	            }
261	        }
262	    }
263	} // end template backSubstituteBasic
264	
265	// ===================================================================================================================
266	// backSubstituteAlt: Re-arrange loops to improve dependencies and throughput, utilizes additional internal buffers
267	// for the diagonal and row accumulations. Arguement B is only written to.
268	template <int RowsColsA, typename BackSubstituteTraits, typename InputType, typename OutputType>
269	void backSubstituteAlt(const InputType A[RowsColsA][RowsColsA], OutputType B[RowsColsA][RowsColsA], int& is_singular) {
270	    typename BackSubstituteTraits::RECIP_T diag_recip, diag_recip_calc;
271	    typename BackSubstituteTraits::RECIP_T diag[RowsColsA];
272	
273	    typename BackSubstituteTraits::MULT_T subst_prod;
274	    typename BackSubstituteTraits::ADD_T subst_prod_sum;
275	    typename BackSubstituteTraits::ADD_T final_sum;
276	    typename BackSubstituteTraits::ADD_T subst_sum;
277	    typename BackSubstituteTraits::ADD_T row_sum[RowsColsA][RowsColsA];
278	
279	    typename BackSubstituteTraits::ADD_T diag_recip_low;
280	    typename BackSubstituteTraits::MULTNEG_T neg_diag_prod;
281	    OutputType select_column_multiplier;
282	    OutputType column_multiplier[RowsColsA];
283	    OutputType subst_prod_m1;
284	
285	    is_singular = 0;
286	diag_loop:
287	    for (int i = 0; i < RowsColsA; i++) {
288	#pragma HLS PIPELINE II = BackSubstituteTraits::DIAG_II
289	        back_substitute_recip(A[i][i], diag_recip_calc);
290	        if (hls::x_real(diag_recip_calc) == 0 && hls::x_imag(diag_recip_calc) == 0) {
291	            is_singular = 1;
292	        }
293	        diag[i] = diag_recip_calc;
294	    }
295	a_col_b_row_loop:
296	    for (int i = 0; i < RowsColsA; i++) {
297	        diag_recip = diag[i];
298	        diag_recip_low = diag_recip; // For fixed-point, reduce precision to match subst_sum for multiplication
299	    a_row_loop:
300	        for (int j = 0; j < RowsColsA; j++) {
301	            if (j >= i) {
302	            b_col_loop:
303	                for (int k = 0; k < RowsColsA; k++) {
304	#pragma HLS PIPELINE II = BackSubstituteTraits::INNER_II
305	
306	                    // Interleaving column results to relax the dependency on the column_multiplier/result calculation
307	                    // o As a result we need an array to store the row accumulations
308	                    if (k <= i) {
309	                        if (i == j) {
310	                            // Top of the column
311	                            if (k == i) {
312	                                // Just the diagonal
313	                                select_column_multiplier = diag_recip;
314	                            } else {
315	                                final_sum = row_sum[k][j];
316	                                neg_diag_prod = -final_sum * diag_recip_low;
317	                                select_column_multiplier = neg_diag_prod;
318	                            }
319	                            column_multiplier[k] = select_column_multiplier;
320	                            B[k][i] = select_column_multiplier; // (B[i][k]) Working with a upper triangular matrix
321	                        } else {
322	                            subst_prod_m1 = A[i][j]; // (A[j][i]) Working with a upper triangular matrix
323	                            subst_prod = subst_prod_m1 * column_multiplier[k];
324	                            subst_prod_sum = subst_prod; // Resize
325	                            if (k == i) {
326	                                // First accumulation in the row sum
327	                                subst_sum = subst_prod_sum;
328	                            } else {
329	                                subst_sum = row_sum[k][j] + subst_prod_sum;
330	                            }
331	                            row_sum[k][j] = subst_sum;
332	                        }
333	                    } else {
334	                        B[k][i] = 0; // Zero lower triangle
335	                    }
336	                }
337	            } else {
338	                continue;
339	            }
340	        }
341	    }
342	} // end template backSubstituteAlt
343	
344	// ===================================================================================================================
345	// backSubstituteTop: Top level function taking a BackSubstituteTraits template parameter which defines internal types
346	// Call this function directly if you wish to override the default internal types
347	template <int RowsColsA, typename BackSubstituteTraits, typename InputType, typename OutputType>
348	void backSubstituteTop(const InputType A[RowsColsA][RowsColsA], OutputType B[RowsColsA][RowsColsA], int& is_singular) {
349	    switch (BackSubstituteTraits::ARCH) {
350	        case 0:
351	            backSubstituteBasic<RowsColsA, BackSubstituteTraits, InputType, OutputType>(A, B, is_singular);
352	            break;
353	        case 1:
354	            backSubstituteAlt<RowsColsA, BackSubstituteTraits, InputType, OutputType>(A, B, is_singular);
355	            break;
356	        default:
357	            backSubstituteBasic<RowsColsA, BackSubstituteTraits, InputType, OutputType>(A, B, is_singular);
358	            break;
359	    }
360	}
361	
362	/**
363	 * @brief backSubstitute
364	 *
365	 * @tparam RowsColsA    Row and column dimensions
366	 * @tparam InputType    Input data type
367	 * @tparam OutputType   Output data type
368	 * @tparam TRIATS       Traits class
369	 *
370	 * @param matrixAStrm   Stream of Input matrix
371	 * @param matrixBStrm   Stream of Output matrix.
372	 * @param is_singular   Indicates the diagonal of B contains zeros.
373	 */
374	template <int RowsColsA,
375	          typename InputType,
376	          typename OutputType,
377	          typename TRAITS = backSubstituteTraits<RowsColsA, InputType, OutputType> >
378	void backSubstitute(hls::stream<InputType>& matrixAStrm, hls::stream<OutputType>& matrixBStrm, int& is_singular) {
379	    InputType A[RowsColsA][RowsColsA];
380	    OutputType B[RowsColsA][RowsColsA];
381	
382	    for (int r = 0; r < RowsColsA; r++) {
383	#pragma HLS PIPELINE
384	        for (int c = 0; c < RowsColsA; c++) {
385	            matrixAStrm.read(A[r][c]);
386	        }
387	    }
388	
389	    backSubstituteTop<RowsColsA, TRAITS, InputType, OutputType>(A, B, is_singular);
390	
391	    for (int r = 0; r < RowsColsA; r++) {
392	#pragma HLS PIPELINE
393	        for (int c = 0; c < RowsColsA; c++) {
394	            matrixBStrm.write(B[r][c]);
395	        }
396	    }
397	}
398	
399	} // end namespace solver
400	} // end namespace xf
401	
402	#endif
